    g.setAttribute('position', new T.Float32BufferAttribute(pos, 3));
    var p = new T.Points(g, new T.PointsMaterial({ color: 0xdfe8ff, size: 1.7, sizeAttenuation: false, fog: false, transparent: true, opacity: 0, depthWrite: false }));
