      d = smin(d, cap(x, y, z, [1.6, 2.68, 0.09, 0.05], [1.57, 2.75, 0.1, 0.035]), 0.03);
      d = smin(d, cap(x, y, z, [1.6, 2.68, -0.09, 0.05], [1.57, 2.75, -0.1, 0.035]), 0.03);
