      d = smin(d, cap(x, y, z, [0, 1.35, -0.21, 0.07], [-0.06, 0.86, -0.25, 0.05]), 0.04);
      d = smin(d, cap(x, y, z, [0.06, 0.06, 0.1, 0.06], [0.2, 0.05, 0.1, 0.05]), 0.03);
      d = smin(d, cap(x, y, z, [-0.1, 0.06, -0.1, 0.06], [0.04, 0.05, -0.1, 0.05]), 0.03);
