    var cloths = ['#7b2d26', '#1f4c58', '#c2a468', '#7b2d26', '#3a2f55', '#1f4c58'].map(function (c) { return std({ color: lin(c), roughness: 0.95 }); });
    var bag = std({ color: lin('#5b4530'), roughness: 0.95 }), geos = [camelGeo(1, cell), camelGeo(-1, cell)], ropes = [], camels = [];
