    var robe = new T.Mesh(herderGeo(q.lod ? 0.04 : 0.03), std({ color: lin('#e8e1d2'), roughness: 0.9 }));
    robe.castShadow = true;
    man.add(robe);
    man.add(new T.Mesh(G.xf(new T.TorusGeometry(0.1, 0.014, 6, 20), -0.01, 1.7, 0, Math.PI / 2, 0, 0), std({ color: lin('#15130f'), roughness: 0.8 })));
    var staff = new T.Mesh(G.cyl(0.016, 0.02, 1.8, 6, 0.27, 0, 0.27), bag);
    staff.castShadow = true;
    man.add(staff);
    man.position.set(hx, groundY(hx, hs), -hs);
    man.rotation.y = TH;
    man.updateMatrix();
