    parts.push(G.bar([0, yj, 0.7], [J, yj, 0.7], 0.2), G.bar([0, yj, -0.7], [J, yj, -0.7], 0.2), G.bar([0, yj + 1.3, 0], [J - 2, yj + 1.3, 0], 0.2));
    for (i = 0; i < J - 3; i += 3) parts.push(G.bar([i, yj, 0.7], [i + 1.5, yj + 1.3, 0], 0.09), G.bar([i + 1.5, yj + 1.3, 0], [i + 3, yj, 0.7], 0.09), G.bar([i, yj, -0.7], [i + 1.5, yj + 1.3, 0], 0.09), G.bar([i + 1.5, yj + 1.3, 0], [i + 3, yj, -0.7], 0.09));
    var cj = J * 0.3;
    parts.push(G.bar([0, yj, 0.7], [-cj, yj, 0.7], 0.2), G.bar([0, yj, -0.7], [-cj, yj, -0.7], 0.2), G.box(3.2, 2.2, 2.2, -cj + 1.8, yj - 2.2, 0));
    parts.push(G.bar([0.5, yj, 0], [0, top, 0], 0.2), G.bar([-0.5, yj, 0], [0, top, 0], 0.2), G.bar([0, top, 0], [J * 0.62, yj + 1.3, 0], 0.07), G.bar([0, top, 0], [-cj + 0.5, yj, 0], 0.07));
    parts.push(G.bar([J * 0.7, yj, 0], [J * 0.7, yj - H * 0.42, 0], 0.05), G.box(0.8, 0.8, 0.8, J * 0.7, yj - H * 0.42 - 0.8, 0));
